5.query:
timeseries {
  cpu = avg(dt.host.cpu.usage),
  memoria = avg(dt.host.memory.usage),
  disco = avg(dt.host.disk.used.percent)
}, by:{dt.smartscape.host}
| fieldsAdd host = getNodeName(dt.smartscape.host),
    cpu_media = arrayAvg(cpu), memoria_media = arrayAvg(memoria), disco_medio = arrayAvg(disco)
| fields host, cpu_media, memoria_media, disco_medio
| sort cpu_media desc
| limit 25

17.query:
timeseries {
  total = sum(dt.service.request.count),
  falhas = sum(dt.service.request.failure_count)
}, by:{dt.service.name}
| fieldsAdd taxa_erro_pct = (falhas[] * 100.0) / total[]
